import { z } from 'zod';
import { EnhancementPrompt } from '../image-prompter/image-prompter.schema';

/** Future enhancer output: actual generated bytes, not a prompt or source URL. */
export interface EnhancedImage {
  buffer: Buffer;
  mimeType: string;
  iteration: number;
}

export interface ImageQaInput {
  runId: string;
  userId: string;
  original: { buffer: Buffer; mimeType: string };
  enhanced: EnhancedImage;
  enhancementPrompt: EnhancementPrompt;
  /** Carry forward the assessment's human-review hold. */
  needsReview: boolean;
}

const score = z.number().min(0).max(1);
export const imageQaEvidenceSchema = z.object({
  confidence: score.describe('Certainty in this evaluation, not image quality'),
  scores: z.object({
    improvement: score,
    editAdherence: score,
    preservation: score,
    artifactFree: score,
  }),
  improved: z.boolean(),
  preservationViolations: z.array(z.string().trim().min(1)).max(20),
  issues: z.array(z.string().trim().min(1)).max(20),
  reason: z.string().trim().min(1).max(4000),
});

export type ImageQaEvidence = z.infer<typeof imageQaEvidenceSchema>;
export interface ImageQaResult extends ImageQaEvidence {
  runId: string;
  iteration: number;
  passed: boolean;
  needsReview: boolean;
  policyVersion: string;
}

/** A cumulative observation for one run, not the independent-sample pass@k estimator. */
export function summarizeQaIterations(attempts: readonly ImageQaResult[]) {
  if (
    attempts.length === 0 ||
    attempts.some(
      (attempt, index) =>
        attempt.iteration !== index + 1 || attempt.runId !== attempts[0].runId,
    )
  ) {
    throw new Error(
      'QA history must contain one run with consecutive iterations starting at 1',
    );
  }
  const last = attempts[attempts.length - 1];
  return {
    runId: last.runId,
    k: last.iteration,
    confidenceAtK: last.confidence,
    passedAtK: last.passed,
    passedByK: attempts.some((attempt) => attempt.passed),
    firstPassedIteration:
      attempts.find((attempt) => attempt.passed)?.iteration ?? null,
  };
}
